(() => {
 const F=FRTB,U=FRTB_UI,{slider,select,bars,n,pct}=U;
 const mean=a=>F.sum(a)/a.length,sd=a=>Math.sqrt(mean(a.map(x=>(x-mean(a))**2))),rms=a=>Math.sqrt(mean(a.map(x=>x*x)));
 const random=SC.rng(1824),raw=Array.from({length:250},()=>SC.normal(random)),raw2=Array.from({length:250},()=>SC.normal(random));
 const standard=a=>a.map(x=>(x-mean(a))/sd(a)),z=standard(raw),b0=standard(raw2),projection=mean(z.map((x,i)=>x*b0[i])),e=standard(b0.map((x,i)=>x-projection*z[i]));
 const paths=(name,a,color)=>({name,data:a.map((x,i)=>[i+1,x]),color});
 const principles=[['construction','1 · Modellable inputs & interpolation'],['capture','2 · Systematic & idiosyncratic risk'],['preserve','3 · Volatility & correlation'],['compare','4 · Four-source consistency'],['review','5 · Review & remediation'],['freshness','6 · Updates & calibration'],['stress','7 · Stress history'],['proxy','8 · Proxies & PLAT consistency']];
 const conditional=(d,ids)=>({...d,when:s=>ids.includes(s.principle)});
 function compute(s){let stats,rows,series,chartBars,explanation,formula,rule,metric,y;
  const tol=s.tolerance/100,observed=z.map((x,i)=>x+s.idio/100*e[i]),model=z.map((x,i)=>x*s.retained/100+s.idio/100*s.capture/100*e[i]),es=a=>F.tail(a,.975).es;
  const diagnostic=(value,limit,lower=true)=>lower?value<=limit:value>=limit;
  if(s.principle==='construction'){
   const x=s.target,inside=x>=1&&x<=5,endpoint=s.eligible==='yes',distance=inside?0:Math.min(Math.abs(x-1),Math.abs(x-5)),permission=s.permission==='yes',aligned=s.aligned==='yes',sound=endpoint&&(inside||permission)&&aligned;
   stats=[['Target maturity',x+'y'],['Outside observed range',distance+'y'],['Evidence gates',sound?'Met as entered':'Action required']];
   series=[{name:'Modellable nodes',data:[[1,2],[3,2.5],[5,3]],dots:true,color:'#187b64'},{name:inside?'Interpolation':'Extrapolation',data:[[1,2],[x,1.75+.25*x]],color:'#bf904b'}];
   rows=[['Source eligibility',endpoint?'Modellable':'Not modellable','Required: model inputs from modellable factors'],['Target bracket',inside?'Within 1–5y':'Outside 1–5y','Interpolation versus extrapolation'],['Permission',permission?'Specified in IMA permission':'Not specified','Required for extrapolation; reasonable distance must also be justified'],['PLAT alignment',aligned?'Same transformation':'Different transformation','Same interpolation / extrapolation must be used in RTPL'],['Distance test',distance+'y','No universal numerical distance limit in this article']];
   explanation='Interpolation is a bridge between supported nodes. Extrapolation extends beyond the evidence: permission and a justified reasonable distance are required. Green evidence gates do not determine whether that distance is reasonable.';formula='Target within [min node, max node] → interpolation; outside → extrapolation';rule='325bh(3–4)';
  }else if(s.principle==='capture'){
   const missed=rms(observed.map((x,i)=>x-model[i]))/sd(observed),gap=1-es(model)/es(observed);metric=missed;
   stats=[['Uncaptured RMS / observed σ',pct(missed)],['ES understatement',pct(gap)],['Teaching tolerance',diagnostic(missed,tol)?'Within tolerance':'Investigate']];
   series=[paths('Observed: market + name',observed,'#187b64'),paths('Model input',model,'#bf904b')];
   rows=[['Systematic amplitude retained',s.retained+'%','Sensitivity to the common market driver'],['Name-specific amplitude retained',s.capture+'%','A sector proxy cannot remove issuer-specific risk'],['Residual RMS / observed σ',pct(missed),'Teaching diagnostic: compare to '+s.tolerance+'%'],['ES impact',pct(gap),'Positive = lower ES using incomplete inputs'],['Regulatory decision','No universal residual threshold','Adequate risk capture; uncaptured stress risks need NMRF capital']];explanation='Two issuers can share the same market driver and still move differently. Turn name-specific capture to zero: a neat market fit can leave meaningful issuer risk outside the model.';formula='Observed = market + idiosyncratic; residual = observed − model';rule='325bh(5)';
  }else if(s.principle==='preserve'){
   const market=z,reference=z.map((x,i)=>.6*x+.8*e[i]),transformed=z.map((x,i)=>s.retained/100*(s.rho/100*x+Math.sqrt(1-(s.rho/100)**2)*e[i])),ratio=sd(transformed)/sd(reference),corr=sd(transformed)>1e-12?F.correlation(market,transformed):null,err=corr===null?1:Math.abs(corr-.6),ok=Math.abs(ratio-1)<=tol&&err<=tol;
   stats=[['Volatility ratio',n(ratio)+'×'],['Correlation with market',corr===null?'Undefined · flat':n(corr)],['Teaching tolerance',ok?'Within tolerance':'Investigate']];series=[paths('Reference factor',reference,'#187b64'),paths('Transformed factor',transformed,'#bf904b')];
   rows=[['Volatility ratio',n(ratio),'Compare |ratio − 1| to '+s.tolerance+'% teaching tolerance'],['Reference correlation','0.600','Synthetic observed relationship to market'],['Transformed correlation',corr===null?'Undefined':n(corr),'Compare absolute correlation difference to '+n(tol)],['Interpretation',ok?'Diagnostics within tolerance':'Transformation alters measured risk','Threshold is adjustable, not a PRA prescribed cutoff']];explanation='Correct volatility does not imply correct dependence. Keep volatility at 100% and change correlation: a hedge can look safer solely because the data transformation changes how factors move together.';formula='Vol ratio = σmodel / σreference; correlation gap = |ρmodel − ρreference|';rule='325bh(6)';
  }else if(s.principle==='compare'){
   const level=Array.from({length:250},(_,i)=>100+F.sum(z.slice(0,i+1))),risk=level.map(v=>100+(v-100)*s.retained/100+s.bias),fo=level,ver=level.map((v,i)=>v+.2*e[i]),ipv=level.map((v,i)=>v-.15*e[i]),chg=a=>a.slice(1).map((x,i)=>x-a[i]),rr=chg(risk),ref=chg(fo),ratio=sd(rr)/sd(ref),gap=mean(risk.map((v,i)=>Math.abs(v-fo[i]))),under=1-es(rr)/es(ref),ok=under<=tol&&gap<=s.levelTolerance;
   stats=[['Mean absolute level gap',n(gap)],['ES understatement',pct(under)],['Teaching diagnostic',ok?'Within tolerance':'Investigate']];series=[paths('Risk model',risk,'#bf904b'),paths('Front office / HPL',fo,'#187b64'),paths('Verifiable prices',ver,'#7e75b0'),paths('Independent verification',ipv,'#467da0')];const levels=[...risk,...fo,...ver,...ipv],lo=Math.min(...levels),hi=Math.max(...levels);y=[lo-1,hi+1];
   rows=[['Levels: mean absolute gap',n(gap),'Compare to '+s.levelTolerance+' price units (teaching limit)'],['Daily-change vol ratio',n(ratio),'Smoothing can lower risk without changing the business'],['Daily-change correlation',sd(rr)>0?n(F.correlation(rr,ref)):'Undefined · flat','High correlation alone does not establish equal tail risk'],['ES understatement',pct(under),'Compare to '+s.tolerance+'% (teaching limit)'],['Review cadence',s.quarters<=1?'At least quarterly':'Review overdue','PRA requires comparison at least quarterly'],['Overlapping evidence','Synthetic sources share a driver','Account for overlap and price uncertainty; assess intraday information too']];
   for(const [name,source]of [['Valuation / HPL',fo],['Verifiable prices',ver],['Independent verification',ipv]]){const changes=chg(source);rows.push(['Risk vs '+name,'Level gap '+n(mean(risk.map((v,i)=>Math.abs(v-source[i]))))+'; vol ratio '+n(sd(rr)/sd(changes)),'Correlation '+(sd(rr)>0?n(F.correlation(rr,changes)):'not defined for flat series')+'; ES understatement '+pct(1-es(rr)/es(changes))]);}
   explanation='The four lines represent risk-model, valuation, real-price and independent verification evidence. Matching direction can coexist with biased levels or compressed daily changes. The synthetic series deliberately share data; four sources are not four independent confirmations.';formula='Compare price levels, daily-change volatility, correlation and ES impact across four sources';rule='325bh(7–8)';
  }else if(s.principle==='review'){
   const input=es(model),benchmark=es(observed),adjusted=s.action==='adjust'?benchmark:input,gap=1-input/benchmark,action=s.action==='none'?'No remediation':s.action==='adjust'?'Inputs restored in this example':'Route affected risk to NMRF';
   stats=[['Detected ES understatement',pct(gap)],['Chosen response',action],['Review record',s.reviewed==='yes'?'Recorded':'Missing']];chartBars=bars(['Reference ES','Raw model ES','After selected action'],[benchmark,input,s.action==='nmrf'?input:adjusted]);rows=[['Detection',pct(gap),'Investigate potential understatement; no universal PRA tolerance'],['Review & escalation',s.reviewed==='yes'?'Completed as entered':'Not completed','Methodology and findings need appropriate review and escalation'],['Adjustment',s.action==='adjust'?'Restored full synthetic series':'No synthetic adjustment','Real changes must be validated, not chosen to force a pass'],['NMRF route',s.action==='nmrf'?'SSRM required':'Not selected','This chart does not calculate the additional SSRM capital'],['Outcome',s.action!=='none'&&s.reviewed==='yes'?'Remediation workflow illustrated':'Open action','Workflow evidence is not regulatory approval']];explanation='Finding a gap is the start of a decision. Restoring risk to inputs and treating a factor as non-modellable are different remedies. Selecting NMRF does not erase the exposure; its stress-scenario charge must be calculated separately.';formula='Detect → review and escalate → adjust risk measurement or consider NMRF treatment';rule='325bh(9), subject to (3)';
  }else if(s.principle==='freshness'){
   const dataOK=s.dataDays<=7||(s.dataDays<=28&&s.justified==='yes'),regOK=s.regDays<=14||s.permission==='yes',quarterOK=s.quarters<=1,aligned=s.aligned==='yes';stats=[['Data update check',dataOK?'Meets entered cadence':'Overdue / unjustified'],['Regression cadence',regOK?'Meets entered cadence':'Overdue / no permission'],['Comparison cadence',quarterOK?'Quarterly or faster':'Overdue']];chartBars=bars(['Data age (days)','Regression age','Quarter review (months)'],[s.dataDays,s.regDays,s.quarters*3]);rows=[['Data updates',s.dataDays+' days','Weekly; justified derogation no less often than monthly'],['Monthly illustration','28-day February interval','This scenario uses a 28-day month; operational checks use calendar dates'],['Regression parameters',s.regDays+' days','At least fortnightly; slower justified frequency specified in IMA permission'],['Slower regression permission',s.permission==='yes'?'Justified selected cadence assumed specified':'Not specified','Sufficient frequency still has to be demonstrated'],['Four-source review',s.quarters+' quarters','At least quarterly'],['Front-office calibration window',aligned?'Same observation period':'Different observation period','Required alignment'],['Missing-data workflow',s.reviewed==='yes'?'Alternative-source and fill policies recorded':'Policies missing','Need timely alternative sources, gap filling and backfilling']];explanation='A statistically good history can still be stale. These are cadence checks against stated PRA requirements, separate from the statistical tolerances. '+(!aligned?'The selected front-office calibration mismatch also requires action.':'Matching calibration periods avoids comparing different market regimes.');formula='Weekly data; fortnightly regression refresh; quarterly source comparison, subject to the stated derogations';rule='325bh(7), (10)';
  }else if(s.principle==='stress'){
   const stressed=z.map(x=>2.5*x),proxy=z.map(x=>2.5*x*s.retained/100),ratio=es(proxy)/es(stressed),evidence=s.justified==='yes',newName=s.newFactor==='yes',include=s.includeIdio==='yes',permitted=!newName||!include||s.permission==='yes';stats=[['Constructed / reference stress ES',n(ratio)+'×'],['Empirical justification',evidence?'Entered as supported':'Missing'],['New-name eligibility gate',permitted?'No selected restriction':'Permission missing']];series=[paths('Similar factor in stress',stressed,'#187b64'),paths('Constructed stress history',proxy,'#bf904b')];rows=[['Stress data default','Actual selected stress-period prices','Alternative prices need the relevant empirical justification'],['Stress ES ratio',n(ratio),'Teaching diagnostic: ≥ '+n(1-tol)+'; no universal PRA cutoff'],['New / changed factor',newName?'New factor in stress period':'Existing factor with changed characteristics','Article 325bh(11–12) governs the exceptions'],['Empirical evidence',evidence?'Provided as an assumption':'Not provided','A statistical ratio alone does not establish justification'],['New name-specific component',include?'Included in reduced set':'Excluded from reduced set',permitted?'Subject to remaining criteria':'Needs specification in IMA permission']];explanation='Stress history must represent a stressed world, not today’s calmer one. A new factor may need evidence from comparable factors, but a constructed series and a high correlation are not enough to justify including a new name-specific component in the reduced set.';formula='Compare constructed stress changes with comparable factors during the selected stress period';rule='325bh(11–12)';
  }else{
   const proxy=z,actual=z.map((x,i)=>x+s.idio/100*e[i]),basis=actual.map((x,i)=>x-proxy[i]),residual=sd(basis)/sd(actual),covered=s.capitalised==='yes',same=s.aligned==='yes',ok=same||covered;stats=[['Proxy correlation',n(F.correlation(actual,proxy))],['Basis σ / actual σ',pct(residual)],['RTPL consistency gate',ok?'Met as entered':'Basis capital missing']];series=[paths('Actual factor',actual,'#187b64'),paths('Proxy factor',proxy,'#bf904b'),paths('Residual basis',basis,'#7e75b0')];rows=[['Residual basis',pct(residual),'Compare to '+s.tolerance+'% teaching tolerance; correlation alone is insufficient'],['Proxy rationale',s.justified==='yes'?'Empirical / conceptual evidence assumed':'Evidence missing','Proxy must represent actual factor characteristics'],['RTPL input',same?'Same proxy as risk model':'Actual factor substituted','Actual factor is permitted only with basis identified and adequately capitalised'],['Basis treatment',covered?'Identified; adequate capital assumed':'Not separately capitalised','ES if modellable, SSRM if non-modellable'],['Decision',ok&&s.justified==='yes'?'Evidence gates illustrated':'Investigate missing conditions','No fixed correlation or residual threshold is prescribed here']];explanation='A proxy borrows another factor’s history. The difference remains your risk. PLAT should use the same proxy; substituting the actual factor requires identifying and adequately capitalising that basis. The capital control is an evidence assumption, not a computed adequacy test.';formula='Basis = actual factor − proxy; compare residual volatility and consistent RTPL treatment';rule='325bh(13–14)';
  }
  return {stats,series,y,bars:chartBars,xlabel:s.principle==='construction'?'Maturity (years) · vertical axis = synthetic yield (%)':'Synthetic day · price / standardised change units',headers:['Check','Computed / entered evidence','Requirement or interpretation'],rows,explanation,formula,key:'PRA reference: '+rule+'. Eight teaching groups organise the article; these are not eight separately numbered PRA principles.',note:'Synthetic, reproducible diagnostics. “Within tolerance” refers to an adjustable teaching limit, not regulatory compliance. Cadence and permission gates are shown separately; evidence inputs require real validation.'};
 }
 window.FRTB_DATA_TEST=compute;
 const lesson={id:'data-tests',name:'Data principles · visual tests',stage:'06 · Model eligibility and data',title:'Test what your model data preserve',intro:'Explore eight groups of PRA data requirements. Each experiment shows a measurable diagnostic, the evidence needed and whether a numerical limit is prescribed.',chart:'Evidence and diagnostics change with your controls',inputs:[select('principle','Data principle',principles,'preserve'),conditional(slider('retained','Market volatility amplitude retained',0,150,5,80,'%'),['capture','preserve','compare','review','stress']),conditional(slider('idio','Name-specific / basis amplitude',0,200,10,80,'%'),['capture','review','proxy']),conditional(slider('capture','Name-specific amplitude retained',0,100,5,50,'%'),['capture','review']),conditional(slider('rho','Transformed correlation',-90,90,5,60,'%'),['preserve']),conditional(slider('bias','Model price-level bias',-10,10,.5,2,'units'),['compare']),conditional(slider('tolerance','Teaching diagnostic tolerance',1,50,1,10,'%'),['capture','preserve','compare','stress','proxy']),conditional(slider('levelTolerance','Teaching level-gap tolerance',.5,10,.5,2,'price units'),['compare']),conditional(slider('target','Target maturity',.5,8,.5,4,'years'),['construction']),conditional(select('eligible','Source node eligibility',[['yes','All nodes modellable'],['no','At least one non-modellable']],'yes'),['construction']),conditional(select('permission','Relevant permission condition',[['no','Not specified'],['yes','Specified; justification assumed']],'no'),['construction','freshness','stress']),conditional(select('aligned','Required model / valuation alignment',[['yes','Aligned'],['no','Not aligned / actual instead of proxy']],'yes'),['construction','freshness','proxy']),conditional(select('justified','Empirical / conceptual justification',[['no','Missing'],['yes','Documented evidence assumed']],'no'),['freshness','stress','proxy']),conditional(select('reviewed','Review / workflow evidence',[['no','Missing'],['yes','Recorded and reviewed']],'no'),['review','freshness']),conditional(select('action','Remediation',[['none','No action'],['adjust','Restore observed input variation'],['nmrf','Treat affected factor as NMRF']],'none'),['review']),conditional(slider('dataDays','Days since data refresh',1,42,1,7,'days'),['freshness']),conditional(slider('regDays','Days since regression refresh',1,60,1,14,'days'),['freshness']),conditional(slider('quarters','Time since four-source comparison',.5,4,.5,1,'quarters'),['freshness','compare']),conditional(select('newFactor','Stress-history exception',[['yes','Factor did not exist in stress'],['no','Existing factor fundamentally changed']],'yes'),['stress']),conditional(select('includeIdio','New name-specific reduced-set component',[['no','Excluded'],['yes','Included']],'no'),['stress']),conditional(select('capitalised','Proxy basis identification / capital',[['no','Not demonstrated'],['yes','Identified and adequately capitalised (assumed)']],'no'),['proxy'])],challenge:'Keep the volatility ratio at one but change correlation. Then compare a statistical diagnostic with a hard update-frequency requirement.',formula:'Measure → compare → investigate → document → remediate',key:'The tests complement RFET and PLAT; they do not replace either.',simpleTitle:'Enough observations is only the first question',simple:'RFET asks whether real-price evidence supports a factor. Data principles ask whether the history used for risk measurement faithfully represents it. Smoothing, stale calibrations, missing issuer risk and weak proxies can all make a well-populated dataset misleading.',scope:'250 synthetic observations with orthogonal standardised drivers. Sample diagnostics are illustrative design choices. Price-change ES is a one-day diagnostic, not liquidity-adjusted FRTB capital. Real testing must account for sampling uncertainty, data overlap, intraday moves, materiality, independent validation and documented evidence.',pages:[[272,'325bh(3–4) · construction'],[273,'325bh(5–8) · risk capture and comparisons'],[274,'325bh(9–12) · remediation, updates and stress'],[275,'325bh(12–14) · new factors and proxies']],notes:[['Which tests have prescribed numbers?','RFET observation routes and PLAT zone thresholds are in separate lessons. This article prescribes update and review frequencies, but not universal RMS, volatility-ratio, correlation-gap or ES-gap pass thresholds. Adjustable limits here illustrate an internal diagnostic, not a regulator-approved test.'],['What happens when data requirements are not met?','Article 325bh(3) routes factors whose inputs fail paragraphs 4–10 to non-modellable treatment. Detecting a potential ES understatement calls for review and escalation and consideration of adjustment or NMRF treatment. Merely increasing a tolerance does not fix a substantive failure.']],compute};
 const index=FRTB_LESSONS.findIndex(l=>l.id==='data');FRTB_LESSONS.splice(index+1,0,lesson);
})();
